// What Hoot says in the UI: short, dry, warm, never generated by the AI (the AI writes only the
// hints and the explanations). All in one file, to review the tone as a whole and translate it
// later.

import type { HootState } from './Hoot';

export type HootMoment =
  | 'home'
  | 'thinking'
  | 'reading'
  | 'retrying'
  | 'right'
  | 'streak'
  | 'wrong'
  | 'levelUp'
  | 'resultsHigh'
  | 'resultsLow'
  | 'replay';

/** `{file}` is replaced by the file being read, `{n}` by a number. */
export const HOOT_LINES: Record<HootMoment, string[]> = {
  home: [
    'Pick a subject, or let me roam the whole project.',
    'Ready when you are. I read the code so you can test what you know.',
    'Every question cites a file of this project. No trivia, promise.',
  ],
  thinking: [
    'Let me look around.',
    'Reading the project. Questions coming up.',
    'Sharpening my pencil. And my glasses.',
  ],
  reading: ['Reading {file}…', 'Looking at {file}…', 'Checking {file}…'],
  retrying: [
    'Some questions did not check out. Rewriting them.',
    'A few citations were off. Fixing them before you see them.',
  ],
  right: ['Nailed it.', 'Exactly.', 'Right on.', 'Correct. You know this code.'],
  streak: ['{n} in a row. Keep it up.', '{n} straight. The code has no secrets for you.'],
  wrong: [
    'Close. Here is what the code does:',
    'Not this time. Have a look at the source:',
    'Not quite. The answer is in the file:',
  ],
  levelUp: ['Level up. Harder questions ahead.', 'Up a level. Let us see how deep it goes.'],
  resultsHigh: ['You know this project well.', 'Impressive. Nothing gets past you.'],
  resultsLow: [
    'Good start. The sources below are worth a read.',
    'Every answer comes with a file to open. Worth a second round.',
  ],
  replay: ['Same questions, no AI call. Show me what stuck.'],
};

/** The Hoot state that goes with a moment. */
export const MOMENT_STATE: Record<HootMoment, HootState> = {
  home: 'idle',
  thinking: 'thinking',
  reading: 'thinking',
  retrying: 'thinking',
  right: 'cheering',
  streak: 'cheering',
  wrong: 'encouraging',
  levelUp: 'cheering',
  resultsHigh: 'cheering',
  resultsLow: 'encouraging',
  replay: 'idle',
};

const last = new Map<HootMoment, string>();

/**
 * A line for `moment`, never the one picked just before for the same moment (when there is a
 * choice). `random` is for the tests.
 */
export function pickLine(
  moment: HootMoment,
  vars: { file?: string; n?: number } = {},
  random: () => number = Math.random,
): string {
  const lines = HOOT_LINES[moment];
  const previous = last.get(moment);
  const choices = lines.length > 1 ? lines.filter((l) => l !== previous) : lines;
  const line = choices[Math.floor(random() * choices.length)] ?? lines[0] ?? '';
  last.set(moment, line);
  return line.replace('{file}', vars.file ?? 'the project').replace('{n}', String(vars.n ?? ''));
}
